import {expect,test} from "vitest";import {fireEvent,render,screen,within} from "@testing-library/react";import {filterArticles} from "./searchModel";import {ArticleSearch} from "./ArticleSearch";import {DecisionMatrix} from "./DecisionMatrix";import {adr,criteria,demoCandidates,equalWeights,rank,type Candidate} from "./decisionModel";import {articles} from "./articles";
test("wyszukiwarka normalizuje zapytanie i nie mutuje listy",()=>{expect(filterArticles(articles,"  HASŁO ").map(article=>article.slug)).toEqual(["reset-hasla"]);expect(filterArticles(articles," ")).toEqual([]);expect(filterArticles(articles,"nie istnieje")).toEqual([]);expect(articles).toHaveLength(2);expect(()=>filterArticles(articles,"a",0)).toThrow();});
test("limit wyników działa po dopasowaniu, w kolejności źródła",()=>{const input=[{slug:"a",title:"API A"},{slug:"b",title:"API B"},{slug:"c",title:"Inne"}];expect(filterArticles(input,"api",1)).toEqual([input[0]]);expect(input).toHaveLength(3);});
test("przenośny komponent reaguje na wpisanie i pokazuje brak wyników",()=>{render(<ArticleSearch articles={articles}/>);fireEvent.change(screen.getByRole("searchbox"),{target:{value:"hasło"}});expect(screen.getByRole("link",{name:"Jak zresetować hasło"})).toHaveAttribute("href","/kb/reset-hasla");fireEvent.change(screen.getByRole("searchbox"),{target:{value:"zzzz"}});expect(screen.getByText("Brak wyników")).toBeVisible();});
test("dwie wyszukiwarki mają odrębne powiązania label-input",()=>{render(<><ArticleSearch articles={articles}/><ArticleSearch articles={articles}/></>);const fields=screen.getAllByRole("searchbox");expect(fields[0].id).not.toBe(fields[1].id);expect(screen.getAllByLabelText("Szukaj w bazie wiedzy")).toHaveLength(2);});
test("twarde ograniczenie statycznego hostingu działa przed punktacją",()=>{const result=rank(demoCandidates,equalWeights,{staticOnly:true,requestHtml:false});expect(result.every(row=>!row.id.endsWith("-ssr"))).toBe(true);expect(result.some(row=>row.id==="next-static")).toBe(true);expect(result.some(row=>row.id==="rr-static")).toBe(true);});
test("sprzeczne wymagania nie wymuszają zwycięzcy",()=>{expect(rank(demoCandidates,equalWeights,{staticOnly:true,requestHtml:true})).toEqual([]);expect(rank(demoCandidates,equalWeights,{staticOnly:false,requestHtml:true}).every(row=>row.id.endsWith("-ssr"))).toBe(true);});
test("wagi zmieniają wynik, bez mutowania danych wejściowych",()=>{const source=JSON.stringify(demoCandidates),content=rank(demoCandidates,{content:10,operations:0,migration:0,interaction:0},{staticOnly:true,requestHtml:false}),interactive=rank(demoCandidates,{content:0,operations:0,migration:0,interaction:10},{staticOnly:true,requestHtml:false});expect(content[0].id).toBe("astro-static");expect(interactive[0].id).toBe("rr-static");expect(JSON.stringify(demoCandidates)).toBe(source);});
test("remis ma deterministyczną kolejność, a błędne skale są odrzucane",()=>{const a:Candidate={id:"a",deployment:"static",requestHtml:false,scores:{content:1,operations:1,migration:1,interaction:1}},b={...a,id:"b"};expect(rank([b,a],equalWeights,{staticOnly:false,requestHtml:false}).map(row=>row.id)).toEqual(["a","b"]);expect(()=>rank([a,a],equalWeights,{staticOnly:false,requestHtml:false})).toThrow("Powtórzony");expect(()=>rank([a],{content:0,operations:0,migration:0,interaction:0},{staticOnly:false,requestHtml:false})).toThrow();expect(()=>rank([{...a,scores:{...a.scores,content:6}}],equalWeights,{staticOnly:false,requestHtml:false})).toThrow();});
test("macierz pokazuje brak zgodnego wariantu i walidację wag",()=>{render(<DecisionMatrix/>);fireEvent.click(screen.getByLabelText("HTML zależny od żądania"));expect(screen.getByRole("status")).toHaveTextContent("Brak wariantu");for(const key of criteria)fireEvent.change(screen.getByLabelText("Waga "+key),{target:{value:"0"}});expect(screen.getByRole("alert")).toHaveTextContent("dodatnia waga");});
test("ADR wymaga alternatyw, dowodów, konsekwencji i warunku ponownej oceny",()=>{const input={context:"Publiczna dokumentacja",choice:"astro-static",alternatives:["next-static"],evidence:["Zbudowany prototyp; brak benchmarku porównawczego"],consequences:"Przebudowanie po zmianie treści",revisit:"Personalizacja HTML"},text=adr(input);expect(text).toContain("## Alternatywy");expect(text).toContain("## Warunek ponownej oceny");expect(text).toContain("brak benchmarku");expect(()=>adr({...input,evidence:[]})).toThrow();expect(()=>adr({...input,revisit:" "})).toThrow();});

